<h2>Tinjauan versi <?= $event['source_version'] ?></h2><p>Event <?= $esc($event['event_id']) ?> · <?= $esc($event['status']) ?></p><p class="muted">Persetujuan hanya berlaku untuk isi versi berikut. Perubahan setelahnya memerlukan persetujuan baru.</p><div class="panel"><strong>Checksum SHA-256</strong><pre><?= $esc($event['checksum']) ?></pre><pre><?= $esc(json_encode(json_decode($event['payload'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)) ?></pre><?php if($event['receipt']): ?><h3>Receipt pusat</h3><pre><?= $esc($event['receipt']) ?></pre><?php endif; ?><div class="actions"><?php if($event['status']==='awaiting'): ?><form method="post" action="<?= $url('approve/'.$event['id']) ?>"><?= $token ?><button>Setujui versi ini</button></form><?php endif; ?><a class="button secondary" href="<?= $url('sync') ?>">Kembali</a></div></div>
